function defaultTheoryBlocks() {
	return [
		{
			id: "b_1",
			type: "heading",
			level: 2,
			content: "1. Khái niệm và đặc điểm chung"
		},
		{
			id: "b_2",
			type: "paragraph",
			content: ""
		},
		{
			id: "b_3",
			type: "example",
			exampleText: "",
			exampleAnalysis: ""
		},
		{
			id: "b_4",
			type: "takeaway",
			takeawayText: ""
		}
	];
}
function initialBlocksFor(theory) {
	if (theory.blocks && theory.blocks.length > 0) return theory.blocks;
	if (theory.sections && theory.sections.length > 0) {
		const generated = [];
		theory.sections.forEach((sec, i) => {
			generated.push({
				id: `b_${Date.now()}_${i}_h`,
				type: "heading",
				level: 2,
				content: sec.title
			});
			sec.body.forEach((p, j) => {
				generated.push({
					id: `b_${Date.now()}_${i}_p_${j}`,
					type: "paragraph",
					content: p
				});
			});
			if (sec.example) generated.push({
				id: `b_${Date.now()}_${i}_ex`,
				type: "example",
				exampleText: sec.example.text,
				exampleAnalysis: sec.example.analysis
			});
			if (sec.takeaway) generated.push({
				id: `b_${Date.now()}_${i}_tk`,
				type: "takeaway",
				takeawayText: sec.takeaway
			});
		});
		return generated;
	}
	return defaultTheoryBlocks();
}
function theorySectionsFromBlocks(blocks) {
	return blocks.filter((b) => b.type === "heading").map((h, idx) => ({
		id: h.id,
		title: h.content || `Phần ${idx + 1}`,
		body: blocks.filter((b) => b.type === "paragraph").map((p) => p.content || ""),
		takeaway: blocks.find((b) => b.type === "takeaway")?.takeawayText || ""
	}));
}
