/**
* Xuất dữ liệu bảng sang file Excel (.xlsx) chuẩn
* Không xuất mật khẩu hoặc thông tin nhạy cảm
*/
function exportToExcel(data, fileName = "mam_van_bao_cao", sheetName = "Số liệu") {
	if (!data || data.length === 0) {
		alert("Không có dữ liệu để xuất file Excel.");
		return;
	}
	const sanitized = data.map((item) => {
		const copy = { ...item };
		delete copy.password_hash;
		delete copy.token;
		delete copy.id;
		return copy;
	});
	const worksheet = utils.json_to_sheet(sanitized);
	const workbook = utils.book_new();
	utils.book_append_sheet(workbook, worksheet, sheetName);
	writeFileSync(workbook, `${fileName}_${(/* @__PURE__ */ new Date()).toISOString().slice(0, 10)}.xlsx`);
}
/**
* In báo cáo hoặc lưu dạng PDF
*/
function printReport() {
	window.print();
}
